#include "font.h"

#include <stdio.h>
#include "cmd.h"

/* Generated by tools/mkfont.py */
extern const font_t font_mono;
extern const font_t font_serif;

/* Font numbers as seen by the user: index + 1. Max FONT_MAX. */
static const font_t *const s_fonts[] = {
	&font_mono,	/* 1 */
	&font_serif,	/* 2 */
};

#define FONT_COUNT	((int)(sizeof(s_fonts) / sizeof(s_fonts[0])))
_Static_assert(FONT_COUNT <= FONT_MAX, "too many fonts");

static const char *fontCmd(int argc, char *argv[], cmdReply_t reply);

esp_err_t fontInit(void)
{
	return cmdRegister("FONT", 0, 0, fontCmd, "FONT  list fonts");
}

int fontCount(void)
{
	return FONT_COUNT;
}

const font_t *fontGet(int id)
{
	return (id >= 1 && id <= FONT_COUNT) ? s_fonts[id - 1] : NULL;
}

const uint8_t *fontGlyph(const font_t *f, char c, int *width)
{
	if ((uint8_t)c < f->first || (uint8_t)c > f->last) {
		c = '?';
	}
	int i = (uint8_t)c - f->first;
	*width = f->widths[i];
	return f->data + f->offsets[i];
}

int fontCharWidth(const font_t *f, char c)
{
	int w;
	fontGlyph(f, c, &w);
	return w;
}

static const char *fontCmd(int argc, char *argv[], cmdReply_t reply)
{
	char line[64];
	for (int i = 0; i < FONT_COUNT; i++) {
		snprintf(line, sizeof(line), "%d %s %u (%s)\n", i + 1, s_fonts[i]->name,
		         s_fonts[i]->height, s_fonts[i]->prop ? "prop" : "fw");
		reply(line);
	}
	return NULL;
}
